from pathlib import Path
import json,html,subprocess,hashlib
out=Path(__file__).resolve().parent
load=lambda name:json.loads((out/name).read_text())
checks=[]
for name in ['world-checks.json','QA-checks.json','interaction-checks.json','boundary-review.json']:
 checks+=load(name)['checks']
report={'ownerVisualApproval':'OPEN','scope':'Local-only; no commit, push or publish','checks':checks,'PASS':sum(x['status']=='PASS' for x in checks),'FAIL':sum(x['status']=='FAIL' for x in checks),'unitJS':100,'python':37,'physicalMobile':'NOT_RUN; Chrome 390x844 touch emulation','changedFiles':(out/'changed-files.txt').read_text().splitlines(),'protectedFiles':10,'performance':{'before':load('performance-before.json'),'after':load('performance-after.json')}}
