(out/'QA.json').write_text(json.dumps(report,indent=2,ensure_ascii=False))
def esc(x):return html.escape(str(x))
def fig(file,label):return f'<figure><a href="{esc(file)}"><img src="{esc(file)}" loading="lazy" alt="{esc(label)}"></a><figcaption>{esc(label)}</figcaption></figure>'
def video(name):
 info=load('walkthrough-'+name+'.json')
 chapters=''.join(f'<button type="button" data-video="{name}" data-time="{c["seconds"]}"><time>{int(c["seconds"])//60}:{int(c["seconds"])%60:02d}</time> {esc(c["chapter"])}</button>' for c in info['timeline'])
 duration=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nw=1:nk=1',str(out/(name+'.mp4'))],text=True))
 return f'<article class="video"><h2>{name.capitalize()} · {int(duration)//60}:{int(duration)%60:02d}</h2><video id="{name}" controls preload="metadata" playsinline poster="{name}-hero.png"><source src="{name}.mp4" type="video/mp4"></video><p><a href="{name}.mp4">Otwórz film / pobierz MP4</a></p><details><summary>Przejdź do fragmentu filmu</summary><div class="chapters">{chapters}</div></details></article>'
