for a,z in zip(report['performance']['before']['sections'],report['performance']['after']['sections']):
 fps=f"{a['scene']['fps']:.1f} / {z['scene']['fps']:.1f}" if a['id']=='projekty' else 'poza aktywnym showroomem'
 body+=f"<tr><td>{a['id']}</td><td>{a['rafMedian']:.1f} / {a['rafP95']:.1f}</td><td>{z['rafMedian']:.1f} / {z['rafP95']:.1f}</td><td>{fps}</td></tr>"
